CREATE TABLE IF NOT EXISTS medical_referrals (id INTEGER PRIMARY KEY AUTOINCREMENT,app_id TEXT NOT NULL DEFAULT 'principal-ed',subject_component TEXT NOT NULL,subject_type TEXT NOT NULL,subject_id TEXT NOT NULL,party_type TEXT NOT NULL CHECK(party_type IN ('staff','student','guardian','external')),party_id TEXT NOT NULL,referral_type TEXT NOT NULL CHECK(referral_type IN ('fitness_review','medication_support','accessibility','emergency_plan','other')),operational_question TEXT NOT NULL,needed_by TEXT,clinical_response TEXT,operational_clearance TEXT NOT NULL DEFAULT 'pending' CHECK(operational_clearance IN ('pending','cleared','cleared_with_conditions','not_cleared')),status TEXT NOT NULL DEFAULT 'open' CHECK(status IN ('open','responded','closed','withdrawn')),referred_by TEXT NOT NULL,responded_by TEXT,responded_at TEXT,created_at TEXT NOT NULL DEFAULT(datetime('now')),updated_at TEXT NOT NULL DEFAULT(datetime('now')));
CREATE INDEX IF NOT EXISTS idx_medical_subject ON medical_referrals(app_id,subject_component,subject_type,subject_id,status);CREATE INDEX IF NOT EXISTS idx_medical_party ON medical_referrals(app_id,party_type,party_id,status);
